const wwStored={...window.WILDWORDOPIA_SELECTION_SYNC.query(),...window.WILDWORDOPIA_SELECTION_SYNC.read()};
const wwAliases={men1:'men',bha2:'bha',genu1:'genu'};
const wwCatalog=window.WILDWORDOPIA_LIBRARY?.characters||window.WILDWORDOPIA_SITE_CATALOG;
// Latest non-deleted official image wins, matching the comparison page.
const wwOfficial=c=>/^(cutefigure|meaning20|meaning30|more20)-/.test(c.campaignEntryId||'');
const wwLatestOfficial=f=>f.candidates.filter(wwOfficial).slice().sort((a,b)=>(Date.parse(b.createdAt||b.updatedAt||'')||0)-(Date.parse(a.createdAt||a.updatedAt||'')||0)||Number(b.candidateId.slice(1))-Number(a.candidateId.slice(1)))[0];
let wwSignature='';
function wwApplySelections(previews={}){
  Object.assign(wwStored,previews);
  const characters=wwCatalog.flatMap(f=>{
    let deleted=new Set();try{deleted=new Set(JSON.parse(localStorage.getItem('wildwordopia.deleted-images.v1')||'[]'))}catch{}
    const available=f.candidates.filter(c=>!deleted.has(f.id+':'+c.candidateId));
    const c=wwLatestOfficial({...f,candidates:available})||available.find(c=>c.candidateId===wwStored[f.id])||available.find(c=>c.candidateId===window.WILDWORDOPIA_SELECTED?.[f.id])||available.find(c=>c.candidateId===f.defaultPreviewCandidateId)||available[0];
    if(!c?.file)return [];
    const kana=f.rootCharacterName?.kana||c.kana||f.meaning;
    return [{...f,candidates:[{...c,file:'library/'+c.file,kana}],file:'library/'+c.file,kana,motifs:c.motifs||[],id:wwAliases[f.id]||f.id}];
  });
  const signature=JSON.stringify(characters.map(c=>[c.id,c.file]));
  if(signature===wwSignature)return;
  const notify=Boolean(wwSignature);wwSignature=signature;
  window.ETYMOPEDIA_BRAINROT={characters};window.WILDWORDOPIA_TOP30={characters};
  if(notify)window.dispatchEvent(new Event('wildwordopia-selection-changed'));
}
wwApplySelections();
window.WILDWORDOPIA_SELECTION_SYNC.connect(wwApplySelections);
